import re
from nltk import word_tokenize
from collections import Counter

def task_func(input_str):
    if not isinstance(input_str, str) or not input_str:
        return {}

    # Normalize to lowercase
    text = input_str.lower()

    # Remove special characters and punctuation, keep word characters and spaces
    text = re.sub(r"[^\w\s]", " ", text)
    text = re.sub(r"\s+", " ", text).strip()

    if not text:
        return {}

    try:
        tokens = word_tokenize(text)
    except LookupError:
        tokens = re.findall(r"\b\w+\b", text)

    words = [token for token in tokens if re.fullmatch(r"\w+", token)]
    return dict(Counter(words))
